        test('bundles sys_variable_values with sys_atf_step', async () => {
            const project = ctx.createProject()
            const testId = project.registerExplicitId('sys_atf_test', 'new_test')
            const stepId = project.registerExplicitId('sys_atf_step', 'logging')
            const variableId = project.registerCoalesceId('sys_variable_value', {
                document: 'sys_atf_step',
                document_key: stepId,
                variable: ToRecordStepConfigs.server.log.variables.log.inputVariableId,
            })

            const file = project.addFile({
                path: 'test.now.ts',
                content: `
import { Test } from '@servicenow/sdk/core'

Test({
    $id: Now.ID['new_test'],
    name: 'ATF Test',
    failOnServerError: true,
}, (atf) => {
    atf.server.log({ $id: Now.ID['logging'], log: 'Hello, World!' })
})
`,
            })

            const diagnostics = (await file.getDiagnostics()).map((d) => d.message)
            expect(diagnostics).toEqual([])

            const files = await file.getOutput()

            const filenames = files.map((f) => path.basename(f.path))

            expect(filenames).toHaveLength(2)
            expect(filenames).toEqual(
                expect.arrayContaining([`sys_atf_step_${stepId}.xml`, `sys_atf_test_${testId}.xml`])
            )

            const stepFileXml = files.find((f) => f.path.endsWith(`sys_atf_step_${stepId}.xml`)).content

            const parsedXml = xmlParser.parse(stepFileXml)

            const deleteVariableValuesElement = parsedXml.record_update.sys_variable_value[0]
            expect(deleteVariableValuesElement).toEqual({
                '@_action': 'delete_multiple',
                '@_query': `document_key=${stepId}`,
            })

            expect(parsedXml.record_update?.sys_atf_step?.sys_id).toBe(stepId)
            expect(parsedXml.record_update?.sys_variable_value[1]?.sys_id).toBe(variableId)
        })

